def transform(grid):
    """Tile the 8-cells with 2x2 squares and L triominoes; encode tile shape."""
    h, w = len(grid), len(grid[0])
    cells = frozenset((r, c) for r in range(h) for c in range(w) if grid[r][c] == 8)
    choices = {p: [] for p in cells}
    for r in range(h - 1):
        for c in range(w - 1):
            block = frozenset(((r, c), (r + 1, c), (r, c + 1), (r + 1, c + 1)))
            if block <= cells:
                tile = (block, 1)
                for p in block:
                    choices[p].append(tile)
            # L triomino color is determined by the missing corner.
            # Colors 2, 3, 4 correspond to missing TL, BL, TR respectively;
            # the remaining fourth orientation maps to 5.
            for missing, color in (((r, c), 2), ((r + 1, c), 3),
                                   ((r, c + 1), 4), ((r + 1, c + 1), 5)):
                shape = block - {missing}
                if shape <= cells:
                    tile = (shape, color)
                    for p in shape:
                        choices[p].append(tile)

    @lru_cache(None)
    def cover(remaining):
        remaining = frozenset(remaining)
        if not remaining:
            return ()
        # Choose the most constrained uncovered cell.
        p = min(remaining, key=lambda q: sum(shape <= remaining for shape, _ in choices[q]))
        for shape, color in choices[p]:
            if shape <= remaining:
                rest = cover(tuple(sorted(remaining - shape)))
                if rest is not None:
                    return ((shape, color),) + rest
        return None

    result = [row[:] for row in grid]
    solution = cover(tuple(sorted(cells)))
    if solution is None:
